properties.query:
let TI = materialize(
    ThreatIntelIndicators
    | summarize arg_max(TimeGenerated, *) by Id
    | where IsDeleted == false and IsActive == true
    | where isempty(ValidUntil) or ValidUntil > now()
    | where ObservableKey in~ ('domain-name:value','url:value')
    | extend IOCType = iff(ObservableKey =~ 'domain-name:value','Domain','URL'), IOCValue=tolower(tostring(ObservableValue))
    | where isnotempty(IOCValue)
    | project IndicatorId=Id, IOCType, IOCValue, Confidence, IndicatorName=tostring(Data.name), IndicatorDescription=tostring(Data.description), Tags
);
let Net = materialize(
    DeviceNetworkEvents
    | where TimeGenerated >= ago(1h)
    | where isnotempty(RemoteUrl)
    | extend RemoteValue=tolower(tostring(RemoteUrl))
    | extend RemoteHost=tolower(iif(RemoteValue startswith 'http://' or RemoteValue startswith 'https://', tostring(parse_url(RemoteValue).Host), tostring(split(RemoteValue,'/')[0])))
    | project TimeGenerated, DeviceName, RemoteIP, RemoteUrl, RemoteValue, RemoteHost, InitiatingProcessFileName, InitiatingProcessCommandLine, UserPrincipalName=InitiatingProcessAccountUpn
);
let DomainMatches =
    Net
    | join kind=inner (TI | where IOCType == 'Domain') on $left.RemoteHost == $right.IOCValue;
let UrlMatches =
    Net
    | join kind=inner (TI | where IOCType == 'URL') on $left.RemoteValue == $right.IOCValue;
union DomainMatches, UrlMatches
| project TimeGenerated, DeviceName, RemoteIP, RemoteUrl, UserPrincipalName, InitiatingProcessFileName, InitiatingProcessCommandLine,
          IOCType, IOCValue, IndicatorId, Confidence, IndicatorName, IndicatorDescription, Tags
